python3 -c "
import pandas as pd
df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')
adj = dict(zip(df['patient_id'], df['emergency_contact_patient_id']))

visited = {}
cycles = []

for node in adj:
    if node not in visited:
        path = []
        curr = node
        while curr in adj and curr not in visited:
            visited[curr] = 'visiting'
            path.append(curr)
            curr = adj[curr]
        if curr in visited and visited[curr] == 'visiting':
            cycle_start = path.index(curr)
            cycles.append(path[cycle_start:])
        for n in path:
            visited[n] = 'visited'

print(f'Found {len(cycles)} cycles:')
for c in cycles:
    print(c)
"

